PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE players (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id),
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  nickname TEXT NOT NULL DEFAULT '',
  age INTEGER NOT NULL,
  position TEXT NOT NULL CHECK(position IN ('GK','DEF','MID','FWD')),
  overall_rating INTEGER NOT NULL,
  skills TEXT NOT NULL,           
  physical TEXT NOT NULL,         
  personality TEXT NOT NULL,      
  life_context TEXT NOT NULL,     
  avatar TEXT NOT NULL,           
  description TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, skills_max TEXT NOT NULL DEFAULT '{}', gk_skills TEXT NOT NULL DEFAULT '{}', gk_skills_max TEXT NOT NULL DEFAULT '{}', hidden_talent INTEGER NOT NULL DEFAULT 0, experience INTEGER NOT NULL DEFAULT 0, residence TEXT, commute_km INTEGER DEFAULT 0, weekly_wage INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', squad_number INTEGER, loan_from_team_id TEXT, loan_until TEXT, suspended_matches INTEGER NOT NULL DEFAULT 0, is_celebrity INTEGER DEFAULT 0, coach_relationship INTEGER NOT NULL DEFAULT 50, parent_club_id TEXT REFERENCES teams(id), next_match_return INTEGER NOT NULL DEFAULT 0, nationality TEXT NOT NULL DEFAULT 'CZ');
